div.script:
			var itemDelUrl = null;
			if (typeof showDeleteConfirmDialog == "undefined")
				function showDeleteConfirmDialog(url) {
					itemDelUrl = url;
	        			var dialogClass = window.GlideModal ? GlideModal : GlideDialogWindow;
	        			var dialog = new dialogClass('glide_confirm_standard');
	        			dialog.setTitle(new GwtMessage().getMessage('Confirmation'));
	        			dialog.setPreference('warning', true);
					dialog.setPreference('focusTrap', true);
					dialog.setPreference('title', new GwtMessage().getMessage("delete_item"));
					dialog.setPreference('onPromptComplete', deleteItem);
        				dialog.render();
				}

			if (typeof deleteItem == "undefined")
				function deleteItem() {
					document.location.href = itemDelUrl + "$[AMP]url=" + encodeURIComponent(document.location.href);
				}

j:if.g:evaluate:
                var jvar_cart_remove_url = GlideappCatalogURLGenerator.getCartRemoveURL(jelly.sysparm_catalog, jelly.sysparm_catalog_view, jelly.jvar_cart_item.getGr().getUniqueValue(), gs.getSessionToken());
                if (!JSUtil.nil(jelly.sysparm_cart_name))
					jvar_cart_remove_url += '$[AMP]sysparm_cart_name=' + jelly.sysparm_cart_name;
                jvar_cart_remove_url;

var item_title = '';
if (!JSUtil.nil(jelly.jvar_cat_item))
	item_title = jelly.jvar_cat_item + '';
item_title;
var item_id = jelly.jvar_cart_item.getID();

var params = {"sysparm_parent_sys_id":jelly.RP.getParameterValue("sysparm_parent_sys_id"), "sysparm_parent_table":jelly.RP.getParameterValue("sysparm_parent_table"), "sysparm_view":jelly.RP.getParameterValue("sysparm_view")};
var jvar_edit_cart_url = GlideappCatalogURLGenerator.getFullItemEditURLWithParams(jelly.jvar_cat_item.getID(), jelly.sysparm_catalog, jelly.sysparm_catalog_view, jelly.jvar_cart_item.getGr().getUniqueValue(), jelly.sysparm_view, jelly.sysparm_processing_hint, jelly.sysparm_cart_name, params);
var jvar_edit_cart_action = "location.assign('" + jvar_edit_cart_url + "'); return false;";
jvar_edit_cart_action;
